entries[466011] = { ["name"] = "Flarendo the Furious", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Being the VIP of VIPs at the Gallagio has its perks, including the keys to this former King of Carnage. Cutting-edge goblin technology allows him to achieve over 100 yards per gallon!\"\nVendor:\nAndo the Gat\nZone:\nLiberation of Undermine\nCost:\n777" }
entries[466012] = { ["name"] = "Thunderdrum Misfire", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Recovered from the Cauldron's bleachers during a particularly gruesome clash. When asked if it was a dud, Torq's operator simply replied: 'Probably?'\"\nVendor:\nAndo the Gat\nZone:\nLiberation of Undermine\nCost:\n500" }
entries[466013] = { ["name"] = "Ochre Delivery Rocket", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Get packages and passengers from point A to B in style!\"\nVendor:\nShredz the Scrapper\nZone:\nUndermine\nCost:\n11375" }
entries[466014] = { ["name"] = "Steamwheedle Supplier", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Supplies you with a quick trip, or your enemies with a large explosion!\"\nDrop:\nSteamwheedle Trove\nZone:\nUndermine" }
entries[466016] = { ["name"] = "The Topskimmer Special", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Smaks is sure this rocket won't explode mid-flight. Absolutely. Positively. 100%. Sure.\"\nVendor:\nSmaks Topskimmer\nZone:\nUndermine\nCost:\n11375" }
entries[466017] = { ["name"] = "Innovation Investigator", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"When the best path to a good idea is going really fast.\"\nVendor:\nSkedgit Cinderbangs\nZone:\nUndermine\nCost:\n25" }
entries[466018] = { ["name"] = "Darkfuse Demolisher", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Excellent at making a mess of things. Not so great at cleaning them up.\"\nVendor:\nSitch Lowdown\nZone:\nUndermine\nCost:\n11375" }
entries[466019] = { ["name"] = "Blackwater Shredder Deluxe Mk 2", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"Best not to ask what happened to Mk 1.\"\nVendor:\nBoatswain HardeeZone:\nUndermineCost:\n8125" }
