entries[467026] = { ["name"] = "Goblomagnetic Bouncing Grenade", ["text"] = "Brann has a chance during combat to toss a GMB grenade at an enemy target dealing moderate Nature damage with a 20% chance to stun for 1.5 sec. This has a 25% chance to bounce to a new target.\n\nThe grenade can safely bounce on party members." }
entries[467029] = { ["name"] = "Impact Conversion Matrix", ["text"] = "Upon entering combat, Brann activates the conversion matrix for 10 sec. A small percent of all party damage dealt during this time is converted to primary stat and split between party members.\n\nAfter the conversion matrix powers down, the primary stat buff persists for 10 sec. This effect cannot occur more than once every 2 min." }
