entries[467034] = { ["name"] = "Reverse Engineered Goblin Death Bomb", ["text"] = "When any player's health falls below 50% during combat, Brann throws a giant bomb that explodes on impact.\n\nThe explosion knocks back and slows surrounding enemies by 45% for 5 sec and heals nearby party members for 35% of their maximum health. Can only occur every 1.5 min." }
entries[467035] = { ["name"] = "Comically Large Magnet", ["text"] = "When Brann uses Gathering Tools , there is a 100% chance to magnetize Discarded Plating to party members granting them 5% of their maximum health as a shield that regenerates out of combat.\n\nGathering Tools\nBrann uses his gathering tools to help players find additional gold, ore, herbs, fish, leathers, and treasures." }
entries[467036] = { ["name"] = "Biofuel Rocket Gear", ["text"] = "Party members are equipped with Biofuel Rocket Gear .\n\nBiofuel\nEach enemy slain fuels the Biofuel Rocket Gear increasing Movement Speed by 2% and Haste by 2% for 10 sec, stacking up to 10 times." }
entries[467037] = { ["name"] = "Pinged Augment Chip", ["text"] = "Brann's maximum health is increased by 4% and his damage and healing done is increased by 20%.\n\nWhile in combat, Brann may become targeted by mechanical bots that fixate on him which can be destroyed or dispelled. If they reach Brann, he will suffer 30% of his maximum health in damage and be stunned for 5 sec." }
